import {segmentHit,distanceToBox} from './flight.js?v=14';
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v)),angle=v=>Math.atan2(Math.sin(v),Math.cos(v));
export class AirPursuit{
 constructor(onEvent=()=>{}){this.onEvent=onEvent;this.fighters=[];this.missiles=[];this.active=false;this.wave=0;this.wait=null;this.sequence=0;this.clock=0;this.serial=0;}
 get alive(){return this.fighters.filter(f=>!f.destroyed);}
 reset(){this.fighters=[];this.missiles=[];this.active=false;this.wave=0;this.wait=null;}
 advanceTime(dt,s,pursuit){if(!Number.isFinite(dt)||dt<=0)return;if(!pursuit){if(this.active)this.reset();return;}this.clock+=dt;const eligible=s.flight&&s.airborne&&!s.shotDown;if(!this.active&&eligible){this.active=true;this.spawn(s,1);return;}if(this.wait!==null){this.wait=Math.max(0,this.wait-dt);if(this.wait===0&&eligible)this.spawn(s,Math.min(3,this.wave+1));}}
 spawn(s,count){this.wave=count;this.wait=null;this.sequence++;for(let i=0;i<count;i++){const side=(i-(count-1)/2)*32,yaw=s.yaw,x=s.x-Math.sin(yaw)*220+Math.cos(yaw)*side,z=s.z-Math.cos(yaw)*220-Math.sin(yaw)*side;const f={id:++this.serial,type:'fighter',x,y:s.y+25+i*8,z,yaw:yaw+Math.PI,pitch:0,bank:0,speed:58,hx:5,hz:7,height:3,destroyed:false,fireIn:1.1+i*.6,pass:0,leg:0};f.onHit=()=>this.destroy(f);this.fighters.push(f);}this.fighters=this.fighters.filter(f=>!f.destroyed);this.onEvent({type:'dispatch',message:`航空隊 ${count}機が接近 · ミサイルに注意`});}
 destroy(f){if(f.destroyed)return false;f.destroyed=true;f.speed=0;this.onEvent({type:'destroyed',position:{x:f.x,y:f.y+1,z:f.z},message:'戦闘機を撃墜'});if(!this.alive.length){this.wait=60;this.onEvent({type:'waiting',message:`次の航空隊 ${Math.min(3,this.wave+1)}機 · 60秒後`});}return true;}
 damage(s,amount=40){if(s.shotDown)return;const key=s.onFoot?'health':'integrity';s[key]=Math.max(0,(s[key]??100)-amount);if(s[key]===0){s.shotDown=true;s.landing=false;}this.onEvent({type:s.shotDown&&!s.airborne?'ground-downed':'hit',position:{x:s.x,y:s.y+.6,z:s.z},message:s.shotDown?'飛行機構が損傷 · 緊急降下':'被弾 · 機体の損傷に注意'});}
 update(dt,s,floor=()=>0,obstacles=[],people=[]){if(!this.active)return;const airborne=s.flight&&s.airborne&&!s.shotDown,groundAttack=!airborne&&!s.shotDown&&groundAttackClear(s,obstacles,people),attack=airborne||groundAttack;for(const f of this.alive){const distance=Math.hypot(s.x-f.x,s.y-f.y,s.z-f.z),focus=s.yaw+clamp(s.viewLook||0,-.5,.5),side=f.id%2?1:-1,lead=Math.max(0,(s.speed||0)-35)*4,waypoints=[[110+lead,0],[195+lead,95*side],[295+lead,25*side]],point=waypoints[f.leg||0],tx=s.x-Math.sin(focus)*point[0]+Math.cos(focus)*point[1],tz=s.z-Math.cos(focus)*point[0]-Math.sin(focus)*point[1],ty=Math.max(floor(f.x,f.z)+25,s.y+12+(f.id%3)*6);if(Math.hypot(tx-f.x,tz-f.z)<35)f.leg=((f.leg||0)+1)%3;const orbit=!attack;const desired=Math.atan2(-(tx-f.x),-(tz-f.z)),turn=clamp(angle(desired-f.yaw),-1.15*dt,1.15*dt);f.yaw+=turn;f.bank+=(clamp(-turn/dt,-.8,.8)-f.bank)*(1-Math.exp(-dt*3));f.pitch+=(clamp(Math.atan2(ty-f.y,Math.hypot(tx-f.x,tz-f.z)),-.5,.5)-f.pitch)*(1-Math.exp(-dt*2));f.speed+=(clamp(s.speed+32,52,110)-f.speed)*dt;f.x-=Math.sin(f.yaw)*Math.cos(f.pitch)*f.speed*dt;f.z-=Math.cos(f.yaw)*Math.cos(f.pitch)*f.speed*dt;f.y=Math.max(floor(f.x,f.z)+20,f.y+Math.sin(f.pitch)*f.speed*dt);f.fireIn=Math.max(0,f.fireIn-dt);const aim=angle(Math.atan2(-(s.x-f.x),-(s.z-f.z))-f.yaw);if(attack&&!orbit&&distance<320&&distance>45&&Math.abs(aim)<.65&&f.fireIn===0&&this.missiles.length<6){f.fireIn=8;this.missiles.push({x:f.x,y:f.y+.6,z:f.z,yaw:f.yaw,pitch:f.pitch,life:0,groundAttack,id:++this.serial});this.onEvent({type:'launch',message:groundAttack?'地上攻撃ミサイル接近 · 回避！':'ミサイル接近 · バンクして回避'});}}
  this.missiles=this.missiles.filter(m=>{if(!airborne&&!groundAttack)return false;m.life+=dt;const goalYaw=Math.atan2(-(s.x-m.x),-(s.z-m.z)),goalPitch=Math.atan2(s.y+.65-m.y,Math.hypot(s.x-m.x,s.z-m.z));if(m.life<3.6&&attack){m.yaw+=clamp(angle(goalYaw-m.yaw),-.7*dt,.7*dt);m.pitch+=clamp(goalPitch-m.pitch,-.55*dt,.55*dt);}const v=100,end={x:m.x-Math.sin(m.yaw)*Math.cos(m.pitch)*v*dt,y:m.y+Math.sin(m.pitch)*v*dt,z:m.z-Math.cos(m.yaw)*Math.cos(m.pitch)*v*dt};let t=attack?segmentHit(m,end,{...s,hx:s.onFoot?.35:1.3,hz:s.onFoot?.35:2.5,height:1.9}):null;let obstruction=end.y<=floor(end.x,end.z)+.15?0:Infinity;for(const b of obstacles){if(Math.abs(b.x-m.x)>b.hx+8||Math.abs(b.z-m.z)>b.hz+8)continue;const hit=segmentHit(m,end,b);if(hit!==null)obstruction=Math.min(obstruction,hit);}if(t!==null&&t<=obstruction){this.damage(s);return false;}if(obstruction!==Infinity){this.onEvent({type:'miss',position:end});return false;}Object.assign(m,end);return m.life<7;});
 }
 snapshot(){return {active:this.active,wave:this.wave,alive:this.alive.length,nextWaveIn:this.wait===null?null:Math.ceil(this.wait),missiles:this.missiles.length,fighters:this.alive.map(f=>({x:Math.round(f.x),y:Math.round(f.y),z:Math.round(f.z),yaw:f.yaw}))};}
}

export function groundAttackClear(s,obstacles=[],people=[]){return !obstacles.some(b=>b.type==='building'&&!b.destroyed&&distanceToBox({x:s.x,y:s.y+1,z:s.z},b)<=80)&&!people.some(p=>!p.destroyed&&Math.hypot(p.x-s.x,(p.y||0)-s.y,p.z-s.z)<=80);}
